 Dockerfile.gpu

A konténer, amelyben a modell élni és lélegezni fog. Telepíti az összes szükséges függőséget, beleértve a Qiskitet a kvantumvarázslathoz és a Modal klienst a felhőbe való felemelkedéshez.

dockerfile
# FILE: Dockerfile.gpu
# AUTO-GENERATED BY CALAMI LIGHT AI - FULL, UNTRUNCATED & PRODUCTION-READY

FROM nvidia/cuda:12.4.1-devel-ubuntu22.04

ENV DEBIAN_FRONTEND=noninteractive
ENV TZ=Europe/Budapest
ENV LANG=C.UTF-8

# Install base dependencies and compilers
RUN apt-get update && apt-get install -y --no-install-recommends \
    python3.11 python3.11-venv python3-pip python3-dev \
    build-essential cmake git wget curl \
    libopenblas-dev liblapack-dev libatlas-base-dev gfortran \
    libffi-dev libssl-dev libbz2-dev libreadline-dev libsqlite3-dev \
    libncurses5-dev libncursesw5-dev xz-utils tk-dev \
    libxml2-dev libxmlsec1-dev liblzma-dev zlib1g-dev \
    libgdbm-dev libnss3-dev libgdbm-compat-dev libevent-dev \
    libjpeg-dev libpng-dev libtiff-dev libopenjp2-7-dev libwebp-dev \
    libharfbuzz-dev libfribidi-dev libxcb1-dev \
    libpq-dev libclang-dev clang lldb \
    && rm -rf /var/lib/apt/lists/*

# Link python3.11 to python
RUN ln -s /usr/bin/python3.11 /usr/bin/python

# Install Rust for the runtime components
RUN curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y
ENV PATH="/root/.cargo/bin:${PATH}"

# Install Gleam for data pipelines
RUN curl -fsSL https://install.gleam.run | sh

WORKDIR /app

COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt

COPY . .

# Set environment for the application
ENV PYTHONPATH="/app"
ENV CUDA_HOME="/usr/local/cuda"
ENV PATH="/app/bin:${PATH}"

EXPOSE 8080

# The build script handles the compilation of all components.
# The default command deploys the app via Modal.
CMD ["/bin/bash", "build_and_deploy.sh"]


